const token = $('Metabase Login').item.json.id;
const dbPath = $('Webhook').item.json.body.db_path;
const dbName = dbPath.split('/').pop();

const resp = $input.item.json;
const dbArray = Array.isArray(resp) ? resp : (resp.data || []);
const found = dbArray.find(db => db.name === dbName);

return [{
  json: {
    token,
    db_name: dbName,
    db_id: found ? found.id : null,
    db_exists: !!found,
    charts: $('Generuj SQL i Zbierz Wykresy').item.json.charts
  }
}];

const prev = $input.item.json;
const db_id = prev.id != null ? prev.id : prev.db_id;
const token = $('Sprawdź DB').item.json.token;
const charts = $('Sprawdź DB').item.json.charts;

return [{ json: { db_id, token, charts } }];

const dashId = $input.item.json.id;
const token = $('Scal DB ID').item.json.token;
const dbId = $('Scal DB ID').item.json.db_id;
const charts = $('Scal DB ID').item.json.charts;
const dateColumn = $('Generuj SQL i Zbierz Wykresy').first().json.date_column || null;

return charts.map(chart => {
  let sql = chart.sql;
  let hasDateFilter = false;

  if (dateColumn && sql.toLowerCase().includes(dateColumn.toLowerCase())) {
    const hasWhere = /\bWHERE\b/i.test(sql);
    const snippet = `[[AND ${dateColumn} >= {{start_date}}]] [[AND ${dateColumn} <= {{end_date}}]]`;

    if (hasWhere) {
      if (/\b(GROUP\s+BY|ORDER\s+BY|LIMIT|HAVING)\b/i.test(sql)) {
        sql = sql.replace(/\b(GROUP\s+BY|ORDER\s+BY|LIMIT|HAVING)\b/i, snippet + ' $1');
      } else {
        sql = sql + ' ' + snippet;
      }
    } else {
      const whereSnippet = `WHERE 1=1 ${snippet}`;
      if (/\b(GROUP\s+BY|ORDER\s+BY|LIMIT|HAVING)\b/i.test(sql)) {
        sql = sql.replace(/\b(GROUP\s+BY|ORDER\s+BY|LIMIT|HAVING)\b/i, whereSnippet + ' $1');
      } else {
        sql = sql + ' ' + whereSnippet;
      }
    }
    hasDateFilter = true;
  }

  return {
    json: {
      dash_id: dashId,
      token,
      db_id: dbId,
      title: chart.title,
      sql,
      display: chart.display,
      columns: chart.columns || [],
      has_date_filter: hasDateFilter
    }
  };
});

