const cards = $input.item.json.cards;
const dashId = $('Przygotuj Wykresy').first().json.dash_id;
const token = $('Przygotuj Wykresy').first().json.token;

const PARAM_START = 'f1c3e2d4-a1b2-c3d4-e5f6-a7b8c9d0e1f2';
const PARAM_END   = 'a2b4c6d8-1234-5678-abcd-ef0123456789';

// Metabase nowszych wersji zwraca native query w dataset_query.stages[0], nie
// dataset_query.native (patrz pamiec projektu) — sprawdzamy oba miejsca.
function getTags(card) {
  return (card.dataset_query?.stages?.[0]?.['template-tags'])
      || (card.dataset_query?.native?.['template-tags'])
      || {};
}

const dashcards = cards.map((card, idx) => {
  const tags = getTags(card);
  const hasFilter = Object.keys(tags).length > 0;
  return {
    id: -(idx + 1),
    card_id: card.id,
    row: Math.floor(idx / 2) * 8,
    col: (idx % 2) * 12,
    size_x: 12,
    size_y: 8,
    parameter_mappings: hasFilter ? [
      {card_id: card.id, parameter_id: PARAM_START, target: ['variable', ['template-tag', 'start_date']]},
      {card_id: card.id, parameter_id: PARAM_END,   target: ['variable', ['template-tag', 'end_date']]}
    ] : []
  };
});

const anyHasFilter = cards.some(c => Object.keys(getTags(c)).length > 0);

const dashParams = anyHasFilter ? [
  {id: PARAM_START, name: 'Data od', slug: 'data_od', type: 'date/single', sectionId: 'date'},
  {id: PARAM_END,   name: 'Data do', slug: 'data_do', type: 'date/single', sectionId: 'date'}
] : [];

return [{ json: { dashcards, dash_id: dashId, token, dashParams } }];

const body = $('Webhook').item.json.body;
const BACKEND = 'http://fastapi_backend:8000';
const OLLAMA = 'http://ollama:11434';
const MODEL = 'qwen2.5-coder:7b';

async function callBackend(path, payload) {
  return await this.helpers.httpRequest({
    method: 'POST',
    url: BACKEND + path,
    body: payload,
    json: true,
  });
}

async function callOllama(prompt) {
  const r = await this.helpers.httpRequest({
    method: 'POST',
    url: OLLAMA + '/api/generate',
    body: { model: MODEL, prompt: prompt, stream: false, format: 'json' },
    json: true,
    timeout: 180000,
  });
  return JSON.parse(r.response || '{}');
}

const planPromptResp = await callBackend('/internal/plan-prompt', {
  goal: body.prompt,
  chart_type: body.chart_type || '',
  description: body.description || '',
  schema_text: body.schema_text || '',
});

let rawPlan = await callOllama(planPromptResp.prompt);

let planResp = await callBackend('/internal/process-plan', {
  raw_plan: rawPlan,
  requested_types: planPromptResp.requested_types,
  n_charts: planPromptResp.n_charts,
  user_prompt: body.prompt,
  is_retry: false,
});

if (planResp.need_retry) {
  const retryPrompt = planPromptResp.prompt +
    "\nUWAGA: POPRZEDNI PLAN byl w obcym jezyku. Pola 'title' i 'goal' MUSZA byc napisane WYLACZNIE po polsku.";
  rawPlan = await callOllama(retryPrompt);
  planResp = await callBackend('/internal/process-plan', {
    raw_plan: rawPlan,
    requested_types: planPromptResp.requested_types,
    n_charts: planPromptResp.n_charts,
    user_prompt: body.prompt,
    is_retry: true,
  });
}

return [{
  json: {
    specs: planResp.specs,
    db_path: body.db_path,
    schema_text: body.schema_text,
    user_prompt: body.prompt,
  },
}];

const input = $input.first().json; // {specs, db_path, schema_text, user_prompt}
const BACKEND = 'http://fastapi_backend:8000';
const OLLAMA = 'http://ollama:11434';
const MODEL = 'qwen2.5-coder:7b';

async function callBackend(path, payload) {
  return await this.helpers.httpRequest({
    method: 'POST',
    url: BACKEND + path,
    body: payload,
    json: true,
  });
}

async function callOllama(prompt) {
  const r = await this.helpers.httpRequest({
    method: 'POST',
    url: OLLAMA + '/api/generate',
    body: { model: MODEL, prompt: prompt, stream: false, format: 'json' },
    json: true,
    timeout: 180000,
  });
  return JSON.parse(r.response || '{}');
}

const charts = [];
for (const spec of input.specs) {
  let sql = '', ok = false, err = '', cols = [], sample = [];
  for (let attempt = 0; attempt < 3; attempt++) {
    const sqlPromptResp = await callBackend('/internal/sql-prompt', {
      goal: spec.goal,
      chart_type: spec.chart_type || '',
      schema_text: input.schema_text,
      prev_sql: sql,
      prev_err: err,
    });
    const rawOut = await callOllama(sqlPromptResp.prompt);
    const rawSql = (rawOut && rawOut.sql) || '';
    const validated = await callBackend('/internal/process-sql-attempt', {
      schema_name: input.db_path,
      chart_type: spec.chart_type || '',
      raw_sql: rawSql,
    });
    sql = validated.sql;
    ok = validated.ok;
    err = validated.error || '';
    cols = validated.columns;
    sample = validated.sample;
    if (ok && sql) break;
  }
  if (!ok || !sql) continue;
  const finalized = await callBackend('/internal/finalize-chart', {
    title: spec.title,
    sql: sql,
    chart_type: spec.chart_type || '',
    columns: cols,
    sample: sample,
    user_prompt: input.user_prompt,
  });
  charts.push({ title: finalized.title, sql: sql, display: finalized.display, columns: cols });
}

const dateColResp = await this.helpers.httpRequest({
  method: 'GET',
  url: BACKEND + '/internal/date-column?schema_name=' + encodeURIComponent(input.db_path),
  json: true,
});

return [{
  json: {
    charts: charts,
    db_path: input.db_path,
    user_prompt: input.user_prompt,
    date_column: dateColResp.date_column || null,
  },
}];
